import csv
import io

def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    lines = raw_csv.splitlines(keepends=True)
    start = 0
    while start < len(lines):
        line = lines[start]
        if not line.strip() or line.lstrip(" \t").startswith("#"):
            start += 1
        else:
            break

    content = "".join(lines[start:])
    if not content:
        return {"columns": [], "rows": []}

    old_limit = csv.field_size_limit()
    try:
        if len(content) > old_limit:
            csv.field_size_limit(len(content))
        reader = csv.reader(io.StringIO(content, newline=""), delimiter=",", quotechar='"')
        columns = next(reader, [])
        rows = list(reader)
    finally:
        csv.field_size_limit(old_limit)

    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    number = 1
    while len(columns) < width:
        name = "extra_" + str(number)
        number += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
